import React, { useState } from 'react';
import './clippreview.css';
import { useLocation } from 'react-router-dom';

function ClipPreview() {
    const location = useLocation();
    const { videoURL, videoData, seoData } = location.state || {};

    const [clipStart, setClipStart] = useState(0);
    const [clipEnd, setClipEnd] = useState(0);

    const handleClip = () => {
        if (clipStart < 0 || clipEnd <= clipStart || clipEnd > videoData.duration) {
            alert("Invalid clip range. Ensure the end time is greater than the start time and within the video duration.");
            return;
        }
        alert("Clip created from ${clipStart} to ${clipEnd} seconds!");
    };

    return (
        <div className="clip-preview-container">
            <h1>Clip Preview</h1>

            {videoData ? (
                <>
                    <h2>{videoData.title}</h2>
                    <video src={videoURL} controls className="preview-video"></video>
                    <div className="clip-controls">
                        <label>
                            Start (seconds):
                            <input
                                type="number"
                                value={clipStart}
                                onChange={(e) => setClipStart(Number(e.target.value))}
                            />
                        </label>
                        <label>
                            End (seconds):
                            <input
                                type="number"
                                value={clipEnd}
                                onChange={(e) => setClipEnd(Number(e.target.value))}
                            />
                        </label>
                        <button onClick={handleClip}>Create Clip</button>
                    </div>
                </>
            ) : (
                <p>No video data available. Please fetch a video first.</p>
            )}
        </div>
    );
}

export default ClipPreview;
